  ('ce343377-a0c2-5201-9ff4-824789e73e89', 8, 2, 72, 'si-tuviera', 'Imagine what you''d do', 'Si tuviera plata…', array['subjuntivo.imperfecto', 'si-hipotetico']::text[], 'informal', 'draft'),
