  ('2fb39a77-4405-52e0-83ee-a83f56d744ad', 8, 6, 76, 'dicen-que', 'Pass on the news', 'Dicen que va a llover', array['noticias', 'dicen-que', 'preterito.llamar-leer']::text[], 'informal', 'draft'),
